import manifest from '../data/generated/responsiveImages.json'

interface ResponsiveImageEntry {
  width: number
  height: number
  variants: [width: number, url: string][]
}

// JSON imports type arrays loosely, so state the shape the script writes.
const images = manifest as unknown as Record<string, ResponsiveImageEntry | undefined>

/**
 * `<img>` attributes that let the browser pick a WebP variant sized for the
 * device (generated by `npm run images`). `sizes` describes how wide the image
 * is rendered; the intrinsic width/height reserve its space before it loads.
 * Images without variants keep their original `src`.
 */
export function responsiveImageProps(src: string, sizes: string) {
  const entry = images[src]
  if (!entry) return { src }

  return {
    src,
    srcSet: entry.variants.map(([width, url]) => `${url} ${width}w`).join(', '),
    sizes,
    width: entry.width,
    height: entry.height,
  }
}

/**
 * The smallest generated size of `src` that is at least `cssWidth` px wide on this screen (its width times the
 * device pixel ratio), or the largest one; the original file when it has no sizes. For pictures that cannot use
 * srcset: a video's `poster` is one URL, so the page picks the size itself, at the same sizes the <img>s use.
 */
export function responsiveSrcFor(src: string, cssWidth: number, pixelRatio = window.devicePixelRatio || 1) {
  const entry = images[src]
  if (!entry || entry.variants.length === 0) return src
  const wanted = cssWidth * pixelRatio
  return (entry.variants.find(([width]) => width >= wanted) ?? entry.variants[entry.variants.length - 1])[1]
}

/**
 * `sizes` for the common layouts. From desktop the container stops growing at
 * 120rem (1920px, --content-max-width), reached at about 125rem with the
 * gutters, so above that the largest images never need more than its width.
 */
export const IMAGE_SIZES = {
  container: '(min-width: 125rem) 120rem, 100vw',
  halfContainer: '(min-width: 125rem) 60rem, (min-width: 48rem) 50vw, 100vw',
  halfFromDesktop: '(min-width: 125rem) 60rem, (min-width: 64rem) 50vw, 100vw',
  // Full-bleed split panel: object-cover fills a frame taller than the image's
  // 1.24:1 ratio (min 52rem desktop, 29rem mobile), so it renders wider than its column.
  splitPanel: '(min-width: 130rem) 50vw, (min-width: 64rem) 65rem, (min-width: 36rem) 100vw, 36rem',
  // Home case rows: 58% of the content width from desktop up; full width
  // minus the gutters on phones.
  homeCaseRow: '(min-width: 64rem) 56vw, 100vw',
} as const
